"""Versioned, platform-owned browser runtime and theme."""

RENDERER_VERSION = "1.1"
RUNTIME_VERSION = "1.1"
ALLOWED_SCENE_KINDS = {"intro", "explain", "practice", "quiz", "recap"}

STYLE = """
:root{color-scheme:light;font-family:var(--font-body,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif);color:var(--ink,#172033);background:var(--canvas,#f4f8fc);font-size:var(--font-size-body,1rem)}*{box-sizing:border-box}body{margin:0;line-height:1.65}.course{max-width:var(--content-max,60rem);margin:auto;padding:var(--space-page,24px)}.course-header{background:var(--accent,#123b68);color:var(--surface,#fff);padding:var(--space-card,24px);border-radius:var(--radius-card,14px)}.course-header h1{margin:0;font-size:var(--font-size-title,2rem)}.course-header p{margin:6px 0 0}.progress{margin:16px 0;color:var(--ink,#36516e)}.scene{display:none;background:var(--surface,#fff);padding:var(--space-card,26px);border-radius:var(--radius-card,14px);box-shadow:0 4px 18px #17324b16}.scene.active{display:block}.scene h2{margin-top:0}.block{white-space:pre-wrap}.steps{padding-left:1.25rem}.steps li{margin:10px 0}.quiz-option{display:block;padding:10px;margin:8px 0;border:1px solid var(--border,#bfd0e2);border-radius:var(--radius-control,8px);cursor:pointer;min-height:var(--touch-min,44px)}.feedback{padding:10px;border-radius:var(--radius-control,8px);background:color-mix(in srgb,var(--accent,#123b68) 10%,var(--surface,#fff))}.nav{display:flex;gap:10px;justify-content:space-between;margin-top:20px}.nav button,.check{font:inherit;padding:9px 14px;min-height:var(--touch-min,44px);border-radius:var(--radius-control,8px);border:1px solid var(--accent,#1d5b97);background:var(--surface,#fff);color:var(--accent,#123b68);cursor:pointer}.nav button:focus-visible,.check:focus-visible,input:focus-visible{outline:var(--focus-width,3px) solid var(--focus,#e69b26);outline-offset:3px}@media(max-width:640px){.course{padding:12px}.scene{padding:18px}.nav button{min-height:44px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:0.01ms!important;animation-iteration-count:1!important;transition-duration:0.01ms!important}}
""".strip() + """
/* Platform-owned layout semantics. */
.course{transition:background .2s ease, color .2s ease}
.layout-cover .course-header{min-height:clamp(180px,32vh,320px);display:flex;flex-direction:column;justify-content:center}
.layout-chapter .scene{border-inline-start:6px solid var(--accent)}
.layout-focus .scene{max-width:46rem;margin-inline:auto}
.layout-steps .scene{counter-reset:course-step;border-block-start:4px solid var(--accent)}
.layout-compare .scene{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-card)}
.layout-steps .scene .component-steps,.layout-practice .scene .component-steps{max-width:44rem;margin-inline:auto}
.layout-recap .scene{border-top:8px solid var(--accent)}
.layout-progress .scene{background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--accent) 8%,var(--surface)))}
.component-callout,.component-key-point,.component-compare,.component-recap{padding:var(--space-card);margin-block:var(--space-card);border:1px solid var(--border);border-radius:var(--radius-card);box-shadow:var(--shadow-card)}
.component-steps label,.component-ordered-steps label,.component-choice label{display:flex;align-items:center;gap:.6rem;min-height:var(--touch-min);padding:.5rem;border-radius:var(--radius-control)}
.component-choice{border:1px solid var(--border);border-radius:var(--radius-card);padding:var(--space-card)}
.component-flashcard,.component-matching,.component-ordering{padding:var(--space-card);margin-block:var(--space-card);border:1px solid var(--border);border-radius:var(--radius-card)}.component-flashcard button,.component-matching button,.component-ordering button{min-height:var(--touch-min);padding:.55rem .75rem;border:1px solid var(--border);border-radius:var(--radius-control);background:var(--surface);color:var(--ink);cursor:pointer}.component-matching{display:grid;gap:.75rem}.matching-left,.matching-right{display:flex;flex-wrap:wrap;gap:.5rem}.component-matching button[data-selected="true"]{outline:var(--focus-width,3px) solid var(--focus)}.component-matching button[data-matched="true"]{background:color-mix(in srgb,var(--accent) 18%,var(--surface))}.component-ordering li{display:flex;align-items:center;gap:.5rem;margin:.5rem 0}.component-ordering li button{min-width:44px}.component-ordering li span{flex:1}
@keyframes courseware-enter{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
[data-motion="subtle"] .scene.active{animation:courseware-enter .22s ease-out}
[data-motion="reduced"] *{animation:none!important;transition:none!important;scroll-behavior:auto!important}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media(forced-colors:active){.component-flashcard,.component-matching,.component-ordering,.component-callout,.component-key-point,.component-compare,.component-recap,.component-choice{forced-color-adjust:auto;border:1px solid CanvasText;background:Canvas;color:CanvasText}.nav button,.check,.component-flashcard button,.component-matching button,.component-ordering button{border:1px solid ButtonText;background:ButtonFace;color:ButtonText}}
@media(max-width:640px){.layout-compare .scene{display:block}.layout-compare .scene>*+*{margin-top:var(--space-card)}}
""".strip()

SCRIPT = """
(()=>{
  let i=0,nonce='',parentOrigin='';
  const root=document.querySelector('.course'),scenes=[...document.querySelectorAll('.scene')],progress=document.querySelector('.progress');
  const context={resource_id:root?.dataset.resourceId||'unknown-resource',release_id:root?.dataset.releaseId||'unknown-release'};
  const safeState=state=>{const result=Object.fromEntries(Object.entries(state||{}).filter(([key])=>['scene_index','scene_count','correct','completed','attempt','duration_ms'].includes(key)));const source=state?.component_state||{},component_state={};if(['front','back','known','review'].includes(source.flashcard?.status))component_state.flashcard={status:source.flashcard.status};if(source.matching&&Array.isArray(source.matching.matched_pair_ids)&&source.matching.matched_pair_ids.every(item=>typeof item==='string'))component_state.matching={matched_pair_ids:[...new Set(source.matching.matched_pair_ids)].slice(0,16),...(typeof source.matching.completed==='boolean'?{completed:source.matching.completed}:{})};if(source.ordering&&Array.isArray(source.ordering.order)&&source.ordering.order.every(item=>typeof item==='string'))component_state.ordering={order:[...new Set(source.ordering.order)].slice(0,16),...(typeof source.ordering.submitted==='boolean'?{submitted:source.ordering.submitted}:{}),...(typeof source.ordering.correct==='boolean'?{correct:source.ordering.correct}:{})};if(Object.keys(component_state).length)result.component_state=component_state;return result};
  const send=(type,extra={})=>{if(parentOrigin)parent.postMessage({type,nonce,...extra},parentOrigin)};
  const emit=event=>{const payload={...event,...context,state:safeState(event.state)};payload.occurrence_id=`runtime:${Date.now()}:${Math.random().toString(16).slice(2)}`;payload.event_id=payload.occurrence_id;try{const key='zhiyu.courseware.learning-events.v1';const queued=JSON.parse(localStorage.getItem(key)||'[]');queued.push(payload);localStorage.setItem(key,JSON.stringify(queued))}catch(_){};if(parentOrigin)parent.postMessage({type:'learning_event',nonce,event:payload},parentOrigin)};
  const sceneId=node=>node?.closest('.scene')?.dataset.sceneId||`scene-${i}`;
  const show=n=>{i=Math.max(0,Math.min(n,Math.max(0,scenes.length-1)));scenes.forEach((s,x)=>s.classList.toggle('active',x===i));if(progress)progress.textContent=`第 ${i+1} / ${scenes.length} 节`;if(scenes[i])emit({event_type:'scene_viewed',scene_id:sceneId(scenes[i]),state:{scene_index:i,scene_count:scenes.length}});send('progress',{scene_index:i,scene_count:scenes.length})};
  const applyRestore=restore=>{if(!restore||typeof restore!=='object')return;const targetId=typeof restore.current_scene_id==='string'?restore.current_scene_id:'';const targetIndex=Number.isInteger(restore.current_scene_index)?restore.current_scene_index:scenes.findIndex(scene=>scene.dataset.sceneId===targetId);if(targetIndex>=0)show(targetIndex);const state=restore.component_state||{},flash=state.flashcard?.status;if(['front','back','known','review'].includes(flash))document.querySelectorAll('[data-flashcard]').forEach(card=>{const front=card.querySelector('.flash-front'),back=card.querySelector('.flash-back');if(front)front.hidden=flash==='back';if(back)back.hidden=flash!=='back';card.dataset.reviewStatus=flash});if(state.ordering?.order)document.querySelectorAll('[data-ordering]').forEach(box=>{const list=box.querySelector('ol'),byId=new Map([...box.querySelectorAll('li')].map(item=>[item.dataset.itemId,item]));state.ordering.order.forEach(id=>{const item=byId.get(id);if(item)list.appendChild(item)})});if(state.matching?.matched_pair_ids)document.querySelectorAll('[data-matching] [data-pair-id]').forEach(button=>{button.dataset.matched=String(state.matching.matched_pair_ids.includes(button.dataset.pairId))})};
  const reset=()=>{i=0;document.querySelectorAll('[data-quiz] input').forEach(input=>{input.checked=false});document.querySelectorAll('.feedback').forEach(feedback=>{feedback.hidden=true;feedback.textContent=''});document.querySelectorAll('[data-flashcard]').forEach(card=>{const front=card.querySelector('.flash-front'),back=card.querySelector('.flash-back');if(front)front.hidden=false;if(back)back.hidden=true});document.querySelectorAll('[data-matching] [data-match]').forEach(button=>{button.dataset.selected='false';button.dataset.matched='false'});document.querySelectorAll('[data-ordering]').forEach(box=>{const list=box.querySelector('ol');const initial=[...box.querySelectorAll('li')].sort((a,b)=>Number(a.dataset.initialOrder)-Number(b.dataset.initialOrder));if(list)initial.forEach(item=>list.appendChild(item))});show(0);window.scrollTo({top:0,behavior:'auto'});send('restart',{scene_index:0,scene_count:scenes.length})};
  document.querySelectorAll('[data-ordering] li').forEach((item,index)=>{item.dataset.initialOrder=String(index);item.dataset.itemId=item.dataset.itemId||`item-${index}`});
  document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n)return show(i+Number(n.dataset.nav));const quiz=e.target.closest('[data-quiz]');if(quiz){const selected=[...quiz.querySelectorAll('input:checked')].map(x=>x.value).sort().join('|'),correct=selected===quiz.dataset.answer,feedback=quiz.querySelector('.feedback');if(feedback){feedback.hidden=false;feedback.textContent=correct?'回答正确。':(quiz.dataset.feedback||'请再回顾相关内容后重试。')}emit({event_type:'answer_submitted',scene_id:sceneId(quiz),state:{correct}});emit({event_type:correct?'answer_correct':'answer_retry',scene_id:sceneId(quiz),state:{correct}});send('quiz_result',{correct});return}const flash=e.target.closest('[data-flashcard]');if(flash){const action=e.target.dataset.flashcardAction,back=flash.querySelector('.flash-back'),front=flash.querySelector('.flash-front');if(action){const status=action==='known'?'known':'review';emit({event_type:action==='known'?'flashcard_known':'flashcard_review',scene_id:sceneId(flash),state:{component_state:{flashcard:{status}}})}else{back.hidden=!back.hidden;front.hidden=!front.hidden;emit({event_type:'flashcard_flipped',scene_id:sceneId(flash),state:{component_state:{flashcard:{status:back.hidden?'front':'back'}}})}}return}const match=e.target.closest('[data-match]');if(match){const box=match.closest('[data-matching]'),side=match.dataset.match,pair=match.dataset.pairId,selected=box.querySelector('[data-match][data-selected="true"]');if(selected&&selected.dataset.match!==side){const same=selected.dataset.pairId===pair;selected.dataset.selected='false';match.dataset.selected='false';if(same){selected.dataset.matched='true';match.dataset.matched='true'}const matched=[...box.querySelectorAll('[data-match][data-matched="true"]')].filter(button=>button.dataset.match==='left').map(button=>button.dataset.pairId),complete=matched.length===Number(box.dataset.pairCount||0),feedback=box.querySelector('.feedback');feedback.hidden=false;feedback.textContent=same?(complete?'配对全部正确。':'配对正确。'):'这组配对不一致，请再试一次。';emit({event_type:'matching_attempt',scene_id:sceneId(box),state:{attempt:1,correct:same,component_state:{matching:{matched_pair_ids:matched,completed:complete}}}})}else{box.querySelectorAll('[data-match][data-selected="true"]').forEach(item=>item.dataset.selected='false');match.dataset.selected='true'}return}const move=e.target.closest('[data-order-move]');if(move){const item=move.closest('li'),list=item?.parentElement;if(item&&list){if(move.dataset.orderMove==='up'&&item.previousElementSibling)list.insertBefore(item,item.previousElementSibling);if(move.dataset.orderMove==='down'&&item.nextElementSibling)list.insertBefore(item.nextElementSibling,item)}return}const order=e.target.closest('[data-order-submit]');if(order){const box=order.closest('[data-ordering]'),actual=[...box.querySelectorAll('li')].map(x=>x.dataset.itemId).join('|'),correct=actual===box.dataset.correctOrder,feedback=box.querySelector('.feedback');feedback.hidden=false;feedback.textContent=correct?'排序正确。':'请调整顺序后重试。';emit({event_type:'ordering_submitted',scene_id:sceneId(box),state:{correct,attempt:1,component_state:{ordering:{order:[...box.querySelectorAll('li')].map(x=>x.dataset.itemId),submitted:true,correct}}}});send('ordering_result',{correct})}});
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-flashcard]')){e.preventDefault();e.target.click()}});
  window.addEventListener('message',e=>{if(e.source!==parent)return;if(e.data?.type==='courseware-init'&&typeof e.data.nonce==='string'&&e.data.nonce&&e.origin&&e.origin!=='null'){nonce=e.data.nonce;parentOrigin=e.origin;applyRestore(e.data.restore);send('progress',{scene_index:i,scene_count:scenes.length})}if(e.data?.type==='courseware-command'&&e.data?.command==='restart'&&e.data?.nonce===nonce&&nonce)reset()});
  show(0)
})();
""".strip()

# Keep the generated runtime readable enough to lint with a JavaScript parser.
# The raw string above is retained as the browser contract, while this bounded
# handler replacement avoids a single deeply nested click expression.
_runtime_lines = SCRIPT.splitlines()
_runtime_lines[12] = """  const submitQuiz=quiz=>{const selected=[...quiz.querySelectorAll('input:checked')].map(item=>item.value).sort().join('|'),correct=selected===quiz.dataset.answer,feedback=quiz.querySelector('.feedback');if(feedback){feedback.hidden=false;feedback.textContent=correct?'回答正确。':(quiz.dataset.feedback||'请再回顾相关内容后重试。')}emit({event_type:'answer_submitted',scene_id:sceneId(quiz),state:{correct}});emit({event_type:correct?'answer_correct':'answer_retry',scene_id:sceneId(quiz),state:{correct}});send('quiz_result',{correct})};
  const toggleFlash=(flash,target)=>{const action=target?.dataset.flashcardAction,back=flash.querySelector('.flash-back'),front=flash.querySelector('.flash-front');if(action){const status=action==='known'?'known':'review';emit({event_type:action==='known'?'flashcard_known':'flashcard_review',scene_id:sceneId(flash),state:{component_state:{flashcard:{status}}}})}else{back.hidden=!back.hidden;front.hidden=!front.hidden;emit({event_type:'flashcard_flipped',scene_id:sceneId(flash),state:{component_state:{flashcard:{status:back.hidden?'front':'back'}}}})}};
  const submitMatch=match=>{const box=match.closest('[data-matching]'),side=match.dataset.match,pair=match.dataset.pairId,selected=box.querySelector('[data-match][data-selected="true"]');if(selected&&selected.dataset.match!==side){const same=selected.dataset.pairId===pair;selected.dataset.selected='false';match.dataset.selected='false';if(same){selected.dataset.matched='true';match.dataset.matched='true'}const matched=[...box.querySelectorAll('[data-match][data-matched="true"]')].filter(item=>item.dataset.match==='left').map(item=>item.dataset.pairId),complete=matched.length===Number(box.dataset.pairCount||0),feedback=box.querySelector('.feedback');feedback.hidden=false;feedback.textContent=same?(complete?'配对全部正确。':'配对正确。'):'这组配对不一致，请再试一次。';emit({event_type:'matching_attempt',scene_id:sceneId(box),state:{attempt:1,correct:same,component_state:{matching:{matched_pair_ids:matched,completed:complete}}}})}else{box.querySelectorAll('[data-match][data-selected="true"]').forEach(item=>item.dataset.selected='false');match.dataset.selected='true'}};
  const submitOrder=order=>{const box=order.closest('[data-ordering]'),items=[...box.querySelectorAll('li')],actual=items.map(item=>item.dataset.itemId).join('|'),correct=actual===box.dataset.correctOrder,feedback=box.querySelector('.feedback');feedback.hidden=false;feedback.textContent=correct?'排序正确。':'请调整顺序后重试。';emit({event_type:'ordering_submitted',scene_id:sceneId(box),state:{correct,attempt:1,component_state:{ordering:{order:items.map(item=>item.dataset.itemId),submitted:true,correct}}}});send('ordering_result',{correct})};
  document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n)return show(i+Number(n.dataset.nav));const quiz=e.target.closest('[data-quiz]');if(quiz)return submitQuiz(quiz);const flash=e.target.closest('[data-flashcard]');if(flash)return toggleFlash(flash,e.target);const match=e.target.closest('[data-match]');if(match)return submitMatch(match);const move=e.target.closest('[data-order-move]');if(move){const item=move.closest('li'),list=item?.parentElement;if(item&&list){if(move.dataset.orderMove==='up'&&item.previousElementSibling)list.insertBefore(item,item.previousElementSibling);if(move.dataset.orderMove==='down'&&item.nextElementSibling)list.insertBefore(item.nextElementSibling,item)}return}const order=e.target.closest('[data-order-submit]');if(order)return submitOrder(order)});"""
SCRIPT = "\n".join(_runtime_lines)
